`,sb=[{title:"IdeYar: Crowdfunding Platform Front-End",github:"https://github.com/mosaic-2/IdeYar-front",tech:"React, Front-End Development, System Design, UI/UX",details:["Led the front-end development and system design for a Kickstarter-inspired web platform, enabling users to create, discover, and fund creative projects.","Architected a scalable and maintainable front-end using React, designing a component-based structure, state management strategy, and RESTful API integration.","Developed key user-facing features, including dynamic project pages, user authentication, profile dashboards, and a streamlined campaign creation process."]},{title:"Medical Image Captioning with BLIP & Flan-T5",github:"https://github.com/abtin81badie/medical-image-captioning",tech:"Image Captioning, PyTorch, Hugging Face, BLIP, Flan-T5",details:["Engineered a two-stage captioning pipeline using BLIP for initial generation and Flan-T5 for refinement, enhancing caption descriptiveness for radiology images.","Fine-tuned the BLIP model on the ROCOv2 dataset to adapt its vision-language understanding to the specialized medical imaging domain.","Developed an automated evaluation framework using BERTScore and ROUGE-L to rigorously measure the semantic similarity and accuracy of generated captions."]},{title:"Persian Video Understanding: Fine-Tuning CLIP & CLIP4Clip",github:"https://github.com/abtin81badie/Deep-Learning",tech:"Multimodal Learning, PyTorch, Video-Text Retrieval",details:["Adapted CLIP and CLIP4Clip models for Persian by fine-tuning on the MSR-VTT dataset with 10,000 translated captions, enabling bilingual video-text retrieval.","Implemented multilingual text encoders with custom tokenization and efficient training on an NVIDIA V100 GPU using weighted contrastive loss and dynamic frame sampling.","Achieved 84.1% R@1 accuracy in Persian text-to-video retrieval, outperforming zero-shot baselines, and developed a reusable GitHub framework for multimodal research."]},{title:"Image Classification DSL: A Language for Deep Learning",github:"https://github.com/abtin81badie/Image-DSL",tech:"Domain-Specific Languages, ANTLR4, Python, TensorFlow",details:["Developed a Domain-Specific Language (DSL) using ANTLR4 and Python to simplify image classification, allowing non-programmers to define models with intuitive syntax.","Designed a custom grammar, built an Abstract Syntax Tree (AST) parser, and created a code generator that produces optimized TensorFlow and Keras models from the DSL.","Reduced model definition code by over 90% and accelerated development time by 10x, enabling rapid, standardized prototyping for ML experimentation."]},{title:"Deep Learning Course Workshops",github:"https://github.com/abtin81badie/Practical-Deep-Learning-Series",tech:"PyTorch, Generative Models, PEFT, CNNs, Transformers",details:["Established a comprehensive workshop series covering fundamentals like NumPy, Pandas, and PyTorch, emphasizing GPU-accelerated tensor operations.","Built a diverse range of models from scratch, including CNNs, RNNs, LSTMs, and generative models like VAEs and Conditional GANs.","Implemented advanced, parameter-efficient fine-tuning (PEFT) techniques, including building a Transformer from the ground up and using LoRA to adapt a Stable Diffusion model."]},{title:"Decision Tree for Fraud Detection",github:"https://github.com/abtin81badie/decision-tree",tech:"Python, Classical Machine Learning",details:["Implemented a classical Decision Tree algorithm from scratch to perform fraud detection, demonstrating an understanding of core ML principles."]},{title:"SVM for Text Classification",github:"https://github.com/abtin81badie/SVM",tech:"Python, NLP, Classical Machine Learning",details:["Built a Support Vector Machine (SVM) from the ground up for the task of classifying text documents."]},{title:"Genetic Algorithm for Clustering",github:"https://github.com/abtin81badie/genetics",tech:"Python, Optimization Algorithms",details:["Engineered a Genetic Algorithm to solve a clustering problem, effectively grouping data points into distinct, optimized clusters."]},{title:"MLP Neural Networks with TensorFlow",github:"https://github.com/abtin81badie/Neural-Network",tech:"Python, TensorFlow, Keras, Deep Learning",details:["Built and trained Multi-Layer Perceptron (MLP) networks for function approximation and CIFAR-10 image classification.","Conducted full hyperparameter tuning to optimize model accuracy and performance."]},{title:"Deep Reinforcement Learning Agents",github:"https://github.com/abtin81badie/RL",tech:"Python, Reinforcement Learning",details:["Engineered deep reinforcement learning agents for pendulum balancing (achieving a 95% success rate) and the game of Othello (reaching an 82% win rate)."]}],db=()=>v.jsx(tb,{id:"projects",children:v.jsxs(eb,{children:[v.jsx(nb,{children:"Projects"}),v.jsx(ab,{children:sb.map((u,r)=>{const s=C.accents[r%C.accents.length];return v.jsxs(lb,{$accent:s,children:[v.jsxs(ib,{children:[v.jsx(ub,{href:u.github,target:"_blank",rel:"noopener noreferrer",children:u.title}),u.github&&v.jsx(I1,{})]}),v.jsx(rb,{children:u.details.map((o,p)=>v.jsx(cb,{children:o},p))}),v.jsx(ob,{children:u.tech.split(",").map(o=>v.jsx(fb,{$accent:s,children:o.trim()},o))})]},r)})})]})}),hb=w.div`
